T=cv2.imread('/app/target.png').mean(2)<128
M=[np.load(f'/app/output/stroke{i}.npy')>=.5 for i in range(4)]
D=cv2.distanceTransform((~T).astype('uint8'),cv2.DIST_L2,5)
sl=(slice(270,750),slice(210,820)); T=T[sl]; D=D[sl]; M=[m[sl] for m in M]
stray_area=T.sum()
def sh(a,dx,dy):
 b=np.zeros_like(a);y0=max(0,dy);y1=min(a.shape[0],a.shape[0]+dy);x0=max(0,dx);x1=min(a.shape[1],a.shape[1]+dx);sy0=max(0,-dy);sy1=min(a.shape[0],a.shape[0]-dy);sx0=max(0,-dx);sx1=min(a.shape[1],a.shape[1]-dx);b[y0:y1,x0:x1]=a[sy0:sy1,sx0:sx1];return b
def metrics(out):
 inter=np.count_nonzero(out&T);union=np.count_nonzero(out|T);iou=inter/union;stray=np.count_nonzero(out&(D>4.51))/stray_area;return iou,stray,inter/stray_area,out.sum()
def obj(out):
 i,st,rec,a=metrics(out);return i-0.8*max(0,st-.035),i,st,rec,a
cur=[m.copy() for m in M]
def union_excl(i):
 others=np.zeros_like(T)
 for k,m in enumerate(cur):
  if k!=i: others|=m
 return others
print('base',obj(np.logical_or.reduce(cur)))
trans=[(0,0)]*4
for it in range(2):
 for i in range(4):
  other=union_excl(i); best=(obj(other|cur[i]),0,0)
  for dy in range(-15,16):
   for dx in range(-15,16):
