    if sc[0]>best[0][0]:best=(sc,dx,dy)
  cur[i]=sh(cur[i],best[1],best[2]);trans[i]=(trans[i][0]+best[1],trans[i][1]+best[2])
  print('iteration',it,'stroke',i,'shift',best[1:],'score',best[0])
print('total translations relative current',trans,'final',obj(np.logical_or.reduce(cur)))
